sql_calls.sql:
SELECT * FROM store.daily_sales
WHERE store_id = '014' AND sale_date BETWEEN '2026-06-01' AND '2026-06-30'
ORDER BY sale_date;

SELECT * FROM store.daily_sales
WHERE date BETWEEN '2026-06-01' AND '2026-06-30'
ORDER BY date, sku;

SELECT sku, name, pack, case_units, case_kg, flow, dc_slot, price_inr, cost_inr
FROM store.products
ORDER BY sku;

SELECT tender, COUNT(*) as txn_count, SUM(amount_inr) as total_amount
FROM payments.pos_payments
GROUP BY tender;

SELECT tender, till_status, COUNT(*) as cnt, SUM(amount_inr) as total_amt
FROM payments.pos_payments
GROUP BY tender, till_status;

SELECT * FROM store.write_offs
WHERE date >= '2026-06-01' AND date <= '2026-06-30'
ORDER BY date, sku;

SELECT * FROM store.forecasts
WHERE sku = 'ATTA-WW-5KG'
ORDER BY date;

SELECT * FROM store.inventory_book
WHERE sku = 'ATTA-WW-5KG'
ORDER BY date;

SELECT sku, name, pack, price_inr, cost_inr
FROM store.products
WHERE name ILIKE '%atta%' OR name ILIKE '%wheat%';

SELECT SUM(net_inr) as total_net_upi
FROM payments.upi_settlements
WHERE settlement_date >= '2026-06-01' AND settlement_date <= '2026-06-30';

SELECT DISTINCT tender
FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT sku, name, pack, price_inr, cost_inr, flow
FROM store.products
ORDER BY sku;

SELECT DISTINCT tender, till_status
FROM payments.pos_payments
ORDER BY tender, till_status;

SELECT COUNT(*) as complaint_count
FROM payments.customer_complaints
WHERE complaint_ts >= '2026-06-01' AND complaint_ts < '2026-07-01';

SELECT COUNT(*) as refund_count
FROM payments.upi_refunds
WHERE requested_ts >= '2026-06-01' AND requested_ts < '2026-07-01';

SELECT sku, name, pack_size
FROM store.products
WHERE name ILIKE '%atta%' OR name ILIKE '%wheat%';

SELECT sku, name, pack, case_units, case_kg
FROM store.products
WHERE name ILIKE '%atta%' OR name ILIKE '%wheat%';

SELECT *
FROM store.products
ORDER BY sku;

SELECT COUNT(*) AS shipment_count
FROM warehouse.shipments
WHERE dispatched_ts >= '2026-06-01' AND dispatched_ts < '2026-07-01';

SELECT SUM(units_sold) AS total_units
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date >= '2026-06-01' AND date <= '2026-06-28';

